cd /tmp/fc-main && python3 - <<'PY'
import re, pathlib, collections, yaml
root = pathlib.Path('.')
dupes = {}
mismatch = []
for p in sorted(root.glob('S*/E*.md')):
    t = p.read_text()
    parts = re.split(r'^---\s*$', t, maxsplit=2, flags=re.MULTILINE)
    meta = yaml.safe_load(parts[1])
    body = parts[2].strip().split('\n\n')
    first = body[0].strip()
    if first != (meta.get('summary') or '').strip():
        mismatch.append((str(p), first[:60], (meta.get('summary') or '')[:60]))
    shas = re.findall(r'^Source: friend/\w+ @ ([0-9a-f]{40})$', t, flags=re.MULTILINE)
    for sha in shas:
        dupes.setdefault(sha, []).append(str(p))
dups = {k:v for k,v in dupes.items() if len(v)>1}
print('files:', len(list(root.glob('S*/E*.md'))))
print('summary/frontmatter mismatches:', len(mismatch))
for m in mismatch[:5]: print('  ', m)
print('duplicate SHAs across transcript:', len(dups))
for k,v in list(dups.items())[:5]: print('  ', k[:10], v)
PY
